{
 "$schema": "urn:semantic-agent-schema:published-language:abstract:v1",
 "$id": "urn:example:sample:chain:v1",
 "title": "鎖",
 "description": "節が次の節を持つ鎖である。",
 "type": "object",
 "required": [
  "$schema",
  "root"
 ],
 "properties": {
  "$schema": {
   "const": "urn:example:sample:chain:v1"
  },
  "root": {
   "title": "最初の節",
   "description": "鎖の最初の節である。",
   "$ref": "#/$defs/node"
  }
 },
 "$defs": {
  "node": {
   "type": "object",
   "title": "節",
   "description": "名前と次の節を持つ。",
   "properties": {
    "name": {
     "type": "string",
     "title": "名前",
     "description": "節の名前である。",
     "x-prompt": {
      "rules": [
       {
        "id": "name-is-noun",
        "rule": "名前は名詞で書く。",
        "why": "動詞だと何の節かが分からない。",
        "check": "名詞句かを見る。",
        "bad": [
         {
          "value": "読む",
          "note": "動詞で、何の節かが分からない。"
         }
        ],
        "good": [
         {
          "value": "目次"
         }
        ]
       }
      ]
     }
    },
    "child": {
     "title": "次の節",
     "description": "次の節である。",
     "$ref": "#/$defs/node"
    }
   }
  }
 }
}

